-- YetkinHibe Faz 1: katalog yazma yolu, profil, dosya arşivi, 2027 çağrı tohumu.
-- Tutarlar kuruştur. Havuz ilan edilmediyse NULL kalır.
-- Yeni enum değeri bu dosyada kullanılmaz (aynı transaction yasağı).

ALTER TYPE "PaymentOrderPurpose" ADD VALUE IF NOT EXISTS 'GRANT_DOSSIER';

ALTER TABLE "yetkinhibe_grant_calls"
  ADD COLUMN IF NOT EXISTS "publication_url" VARCHAR(500);

CREATE TABLE IF NOT EXISTS "hibe_grant_call_revisions" (
    "id" TEXT NOT NULL,
    "call_id" VARCHAR(120) NOT NULL,
    "data_version" INTEGER NOT NULL,
    "action" VARCHAR(40) NOT NULL,
    "actor_user_id" TEXT,
    "snapshot_json" JSONB NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "hibe_grant_call_revisions_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hibe_company_profiles" (
    "id" TEXT NOT NULL,
    "user_id" TEXT NOT NULL,
    "business_name" VARCHAR(160) NOT NULL,
    "audience" VARCHAR(40) NOT NULL,
    "province_code" VARCHAR(8) NOT NULL,
    "nace_group" VARCHAR(8) NOT NULL,
    "investment_focus" VARCHAR(40) NOT NULL,
    "employee_count" INTEGER NOT NULL,
    "company_age_years" INTEGER NOT NULL,
    "rd_maturity_level" VARCHAR(20) NOT NULL,
    "export_active" BOOLEAN NOT NULL,
    "has_patent_or_utility_model" BOOLEAN NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    CONSTRAINT "hibe_company_profiles_pkey" PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "hibe_dossiers" (
    "id" TEXT NOT NULL,
    "user_id" TEXT NOT NULL,
    "grant_id" VARCHAR(120),
    "title" VARCHAR(300) NOT NULL,
    "markdown" TEXT NOT NULL,
    "report_json" JSONB NOT NULL,
    "command_key" VARCHAR(80) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "hibe_dossiers_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "hibe_company_profiles_user_id_key" ON "hibe_company_profiles"("user_id");
CREATE UNIQUE INDEX IF NOT EXISTS "hibe_dossiers_user_id_command_key_key" ON "hibe_dossiers"("user_id", "command_key");
CREATE INDEX IF NOT EXISTS "hibe_dossiers_user_id_created_at_idx" ON "hibe_dossiers"("user_id", "created_at");
CREATE INDEX IF NOT EXISTS "hibe_grant_call_revisions_call_id_data_version_idx" ON "hibe_grant_call_revisions"("call_id", "data_version");

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'hibe_grant_call_revisions_call_id_fkey') THEN
    ALTER TABLE "hibe_grant_call_revisions"
      ADD CONSTRAINT "hibe_grant_call_revisions_call_id_fkey"
      FOREIGN KEY ("call_id") REFERENCES "yetkinhibe_grant_calls"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'hibe_grant_call_revisions_actor_user_id_fkey') THEN
    ALTER TABLE "hibe_grant_call_revisions"
      ADD CONSTRAINT "hibe_grant_call_revisions_actor_user_id_fkey"
      FOREIGN KEY ("actor_user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'hibe_company_profiles_user_id_fkey') THEN
    ALTER TABLE "hibe_company_profiles"
      ADD CONSTRAINT "hibe_company_profiles_user_id_fkey"
      FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'hibe_dossiers_user_id_fkey') THEN
    ALTER TABLE "hibe_dossiers"
      ADD CONSTRAINT "hibe_dossiers_user_id_fkey"
      FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION yetkin_forbid_grant_revision_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'hibe_grant_call_revisions is append-only';
END;
$$;

DROP TRIGGER IF EXISTS hibe_grant_call_revisions_append_only ON "hibe_grant_call_revisions";
CREATE TRIGGER hibe_grant_call_revisions_append_only
  BEFORE UPDATE OR DELETE ON "hibe_grant_call_revisions"
  FOR EACH ROW
  EXECUTE PROCEDURE yetkin_forbid_grant_revision_mutation();

-- FORCE ROW LEVEL SECURITY + rls_deny_unscoped. Kullanıcı tablolarında rls_own_user_id.
DO $$
DECLARE
  tbl text;
BEGIN
  FOREACH tbl IN ARRAY ARRAY[
    'hibe_grant_call_revisions',
    'hibe_company_profiles',
    'hibe_dossiers'
  ]
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', tbl);
    EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', tbl);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
       AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated')
       AND NOT EXISTS (
         SELECT 1 FROM pg_policies
         WHERE schemaname = 'public' AND tablename = tbl AND policyname = 'rls_deny_unscoped'
       ) THEN
      EXECUTE format(
        'CREATE POLICY rls_deny_unscoped ON public.%I FOR SELECT TO anon, authenticated USING (false)',
        tbl
      );
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'yetkin_apply_rls_owner_policies'
  ) THEN
    PERFORM public.yetkin_apply_rls_owner_policies('hibe_company_profiles');
    PERFORM public.yetkin_apply_rls_owner_policies('hibe_dossiers');
  END IF;
END $$;

